R["pi-cap-1-repo"] = "import sqlite3\n\nclass TaskError(Exception):\n    pass\n\ndef init_tasks(conn):\n    conn.execute('''CREATE TABLE tasks (\n        id INTEGER PRIMARY KEY,\n        title TEXT NOT NULL UNIQUE,\n        done INTEGER NOT NULL DEFAULT 0\n    )''')\n    conn.commit()\n\nclass TaskRepository:\n    def __init__(self, conn):\n        self._conn = conn\n\n    def add(self, title):\n        try:\n            cur = self._conn.execute('INSERT INTO tasks (title) VALUES (?)', (title,))\n            self._conn.commit()\n            return cur.lastrowid\n        except sqlite3.IntegrityError as exc:\n            raise TaskError('duplicate title') from exc\n\n    def get(self, task_id):\n        row = self._conn.execute(\n            'SELECT id, title, done FROM tasks WHERE id = ?', (task_id,)\n        ).fetchone()\n        return dict(row) if row else None\n\n    def complete(self, task_id):\n        cur = self._conn.execute(\n            'UPDATE tasks SET done = 1 WHERE id = ? AND done = 0', (task_id,)\n        )\n        self._conn.commit()\n        return cur.rowcount == 1\n\n    def list_open(self):\n        return [\n            dict(r)\n            for r in self._conn.execute(\n                'SELECT id, title, done FROM tasks WHERE done = 0 ORDER BY id'\n            )\n        ]";
